  linen: (c = '#173d32') => mat({ color: c, rough: .95, bump: .02, h: 'sin(p.x*26.)*.5+sin(p.y*26.)*.5', tint: 'c*(.8+.3*vn(p*9.))', extra: { sheen: .6, sheenColor: new THREE.Color('#5d8a73'), side: 2 } }),
  brass: () => mat({ color: '#c79a48', rough: .34, metal: 1, extra: { envMapIntensity: 3.2 }, bump: .01, h: 'fbm(p*4.)', tint: 'c*(.75+.45*fbm(p*2.))' }),
  steel: () => mat({ color: '#d3d6d4', rough: .34, metal: 1, extra: { envMapIntensity: 2.8 } }),
  ivory: () => mat({ color: '#efe6d3', rough: .8, bump: .01, h: 'fbm(p*8.)', tint: 'c*(.95+.08*vn(p*20.))' }),
  green: () => mat({ color: '#173d32', rough: .68, bump: .01, h: 'fbm(p*8.)', tint: 'c*(.92+.12*vn(p*20.))' }),
  maroon: () => mat({ color: '#5d2227', rough: .7 }),
  kraft: () => mat({ color: '#b58d5f', rough: .85, bump: .01, h: 'fbm(p*8.)', tint: 'c*(.85+.25*fbm(p*5.))' }),
  jute: () => mat({ color: '#b3935f', rough: .95, bump: .06, h: 'sin(p.y*16.)*.5+sin(atan(p.x,p.z)*110.)*.5', tint: 'c*(.7+.5*vn(p*7.))', extra: { side: 2 } }),
  glass: () => new THREE.MeshPhysicalMaterial({ color: '#f4f8f4', roughness: .05, transparent: true, opacity: .07, envMapIntensity: 2, side: 2, depthWrite: false }),
  gold: () => mat({ color: '#cfae64', rough: .32, metal: 1, extra: { envMapIntensity: 2.6 } }),
