const cache = {}; const mm = (k) => (cache[k] ||= M[k] ? M[k]() : mat(matSpec(k)));

function shape(fn, det) { const g = new THREE.IcosahedronGeometry(1, det); const p = g.attributes.position; const v = V(); for (let i = 0; i < p.count; i++) { v.fromBufferAttribute(p, i); fn(v); p.setXYZ(i, v.x, v.y, v.z); } return smooth(g); }
