  const p = g.attributes.position, map = new Map(), idx = [], out = [];
  for (let i = 0; i < p.count; i++) { const k = [p.getX(i), p.getY(i), p.getZ(i)].map(x => Math.round(x * 5e3)).join(); if (!map.has(k)) { map.set(k, out.length / 3); out.push(p.getX(i), p.getY(i), p.getZ(i)); } idx.push(map.get(k)); }
