    const b = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(cx + Math.cos(a) * r * sx, spawnY + i * .16, cz + Math.sin(a) * r * sz).setRotation(q).setLinvel(0, -6, 0).setLinearDamping(.4).setAngularDamping(1.2));
